"""Fixed root observer/launcher REVIEW CANDIDATE. CLI has no live launch mode.

Only metadata, fresh preparation, and fixed runuser spawning. No namespace,
mount, arbitrary command or alternate Python-loader API here. Root may acquire
and emergency-signal only original direct R through its retained pidfd. Such
disposal is always failure and never recursive O/N teardown evidence.
"""
import dataclasses
import hashlib
import json
import os
from pathlib import Path
import select
import signal
import stat
import time

BASE = Path(__file__).resolve().parent
SOURCE = BASE / 'source'
ATTEMPT = BASE / 'attempt'
INPUT = ATTEMPT / 'input'
EVIDENCE = ATTEMPT / 'evidence'
PINNED = {
    'linux_driver.py': '8708967dcb39e2e698dea61ebe1ab2c730bd54024958a8c924454ee93754bae0',
    'kernel_preflight.py': 'b8d6631286c6bbc65b32a78e77b1f3935b3d01a126e1e24c304c029b296cd7c1',
}
COMMAND = ('/usr/sbin/runuser', '-u', 'freedomqual', '--', '/usr/bin/aa-exec',
           '-p', 'freedom-appimage-qualification', '--', '/usr/bin/python3', '-B',
           str(SOURCE / 'kernel_preflight.py'), '--evidence', str(EVIDENCE),
           '--test-input', str(INPUT))
ENVIRONMENT = {'PATH': '/usr/bin:/bin', 'LANG': 'C.UTF-8'}
PROOF_SECONDS, INNER_SECONDS, OWNER_SECONDS = 22, 24, 26
WRAPPER_NORMAL_SECONDS, TOTAL_SECONDS = 28, 30
MAX_PROC_ENTRIES, CENSUS_SECONDS, MAX_COMMAND_OUTPUT = 4096, 2, 32768


class Refused(RuntimeError):
    pass


def bounded_text(path, maximum=262144):
    with open(path, 'rb') as stream:
        data = stream.read(maximum + 1)
    if len(data) > maximum:
        raise Refused('metadata byte bound: ' + str(path))
    return data.decode('utf8', errors='strict')


def start_time(text):
    fields = text[text.rfind(')') + 2:].split()
    if text.rfind(')') < 0 or len(fields) < 20 or not fields[19].isdigit():
        raise Refused('malformed observer stat')
    return fields[19]


def unshifted_ids(mapping):
    try:
        rows = [tuple(map(int, line.split())) for line in mapping.splitlines()]
    except ValueError as exc:
        raise Refused('malformed ID map') from exc
    if any(len(row) != 3 for row in rows):
        raise Refused('malformed ID map')
    return all(any(inside <= value < inside + count and outside + value - inside == value
                   for inside, outside, count in rows) for value in (0, 1001))


def observer_scope():
    """Read only this running root observer, never substitute another tool's view."""
    scope = {'pid': os.getpid(), 'start': start_time(bounded_text('/proc/self/stat')),
             'uid': os.getuid(), 'euid': os.geteuid(), 'gid': os.getgid(), 'egid': os.getegid(),
             'uid_map': bounded_text('/proc/self/uid_map'),
             'gid_map': bounded_text('/proc/self/gid_map'),
             'namespaces': {name: os.readlink('/proc/self/ns/' + name)
                            for name in ('user', 'mnt', 'pid')},
             'proc1_namespaces': {name: os.readlink('/proc/1/ns/' + name)
                                  for name in ('user', 'mnt', 'pid')}}
    if any(scope[name] != 0 for name in ('uid', 'euid', 'gid', 'egid')):
        raise Refused('fixed launcher requires root metadata/preparation context')
    if not unshifted_ids(scope['uid_map']) or not unshifted_ids(scope['gid_map']):
        raise Refused('root observer cannot identify host UID/GID1001 without shift')
    if scope['namespaces'] != scope['proc1_namespaces']:
        raise Refused('observer/proc1 namespace scope differs; no fallback observer')
    return scope


def require_same_scope(before, after):
    if before != after:
        raise Refused('observer PID/start/identity/maps/namespaces changed')


def census(scope):
    """Bounded read-only census; permission errors or too much churn refuse."""
    began = time.monotonic()
    numeric = []
    for index, path in enumerate(Path('/proc').iterdir()):
        if index >= MAX_PROC_ENTRIES * 2 or time.monotonic() - began >= CENSUS_SECONDS:
            raise Refused('proc census directory/time bound')
        if path.name.isdigit():
            numeric.append(path)
            if len(numeric) > MAX_PROC_ENTRIES:
                raise Refused('proc census entry bound')
    found, vanished = [], 0
    for path in numeric:
        if time.monotonic() - began >= CENSUS_SECONDS:
            raise Refused('proc census time bound')
        try:
            fields = dict(line.split(':', 1) for line in bounded_text(path / 'status', 16384).splitlines() if ':' in line)
            uids = tuple(map(int, fields['Uid'].split()))
            if len(uids) != 4:
                raise Refused('incomplete process UID metadata')
            if 1001 in uids:
                found.append({'pid_observed_here': int(path.name), 'uids': uids,
                              'start': start_time(bounded_text(path / 'stat', 16384)),
                              'state': fields.get('State', '').strip()})
        except FileNotFoundError:
            vanished += 1
            # Conservative rather than counting a changing census as clean.
    require_same_scope(scope, observer_scope())
    if vanished:
        raise Refused('process census changed during reads; no clean census claim')
    return found


def snapshot(expected=None):
    scope = observer_scope()
    if expected is not None:
        require_same_scope(expected, scope)
    processes = census(scope)
    mounts = bounded_text('/proc/self/mountinfo', 1048576)
    require_same_scope(scope, observer_scope())
    return {'scope': scope, 'uid1001_processes': processes,
            'mountinfo_sha256': hashlib.sha256(mounts.encode()).hexdigest()}


def compare_snapshots(before, after):
    require_same_scope(before['scope'], after['scope'])
    if before['uid1001_processes'] or after['uid1001_processes']:
        raise Refused('UID1001 not empty at baseline/final')
    if before['mountinfo_sha256'] != after['mountinfo_sha256']:
        raise Refused('same-observer mountinfo changed')


def verify_sources():
    for directory in (BASE, SOURCE):
        meta = directory.lstat()
        if (not stat.S_ISDIR(meta.st_mode) or meta.st_uid != 0 or meta.st_gid != 0
                or stat.S_IMODE(meta.st_mode) != 0o755):
            raise Refused('fresh root-owned0755 source ancestry required')
    if set(path.name for path in SOURCE.iterdir()) != set(PINNED):
        raise Refused('source directory must contain exactly the two reviewed modules')
    result = {}
    for name, expected in PINNED.items():
        path = SOURCE / name
        meta = path.lstat()
        if (not stat.S_ISREG(meta.st_mode) or meta.st_uid != 0 or meta.st_gid != 0
                or stat.S_IMODE(meta.st_mode) != 0o444):
            raise Refused('root-owned0444 reviewed source file required')
        digest = hashlib.sha256(bounded_text(path).encode()).hexdigest()
        if digest != expected:
            raise Refused('reviewed source hash mismatch: ' + name)
        result[name] = {'sha256': digest, 'uid': meta.st_uid, 'gid': meta.st_gid, 'mode': '0444'}
    return result


def prepare_fresh():
    """Only create/chown/chmod fresh owned paths; never repair or reuse old paths."""
    if ATTEMPT.exists() or ATTEMPT.is_symlink():
        raise Refused('attempt path already exists; no retry/reuse')
    ATTEMPT.mkdir(mode=0o755)
    os.chmod(ATTEMPT, 0o755)
    INPUT.mkdir(mode=0o555)
    os.chmod(INPUT, 0o555)
    EVIDENCE.mkdir(mode=0o700)
    os.chown(EVIDENCE, 1001, 1001)
    os.chmod(EVIDENCE, 0o700)


@dataclasses.dataclass
class DirectCommand:
    pid: int
    reaped: bool = False
    terminal: dict | None = None
    raw_status: int | None = None
    pidfd: int | None = None
    signal_authority: bool = False
    setup_error: str | None = None
    intervention: bool = False
    retired: bool = False
    reaped_at: float | None = None


@dataclasses.dataclass
class OriginalSlot:
    child: DirectCommand | None = None


def spawn_fixed(stdout_fd, slot):
    """Track original R before pidfd acquisition; no reaper/other thread exists."""
    if slot.child is not None or stdout_fd <= 2:
        raise Refused('invalid fresh direct-wrapper slot/output descriptor')
    actions = [(os.POSIX_SPAWN_OPEN, 0, '/dev/null', os.O_RDONLY, 0),
               (os.POSIX_SPAWN_DUP2, stdout_fd, 1), (os.POSIX_SPAWN_DUP2, stdout_fd, 2),
               (os.POSIX_SPAWN_CLOSE, stdout_fd)]
    mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGALRM})
    try:
        pid = os.posix_spawn(COMMAND[0], COMMAND, ENVIRONMENT, file_actions=actions,
                             setsigmask=mask, setsigdef=(signal.SIGALRM,))
        slot.child = DirectCommand(pid)  # Retained even if open/restore raises.
        try:
            slot.child.pidfd = os.pidfd_open(pid, 0)
            slot.child.signal_authority = True
        except BaseException as exc:
            slot.child.setup_error = type(exc).__name__ + ': ' + str(exc)
        return slot.child
    finally:
        signal.pthread_sigmask(signal.SIG_SETMASK, mask)


def retire_authority(child, record):
    """Retire BEFORE sole reap, including before closing a possibly errored fd."""
    child.signal_authority = False
    child.retired = True
    fd, child.pidfd = child.pidfd, None
    if fd is not None:
        try:
            os.close(fd)
        finally:
            record({'type': 'R-authority-retired', 'pid': child.pid})


def peek_reap_command(child, record=lambda _e: None):
    if child.reaped:
        raise Refused('duplicate direct-wrapper reap')
    info = os.waitid(os.P_PID, child.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT)
    if info is None:
        return False
    if info.si_pid != child.pid or info.si_code not in (os.CLD_EXITED, os.CLD_KILLED, os.CLD_DUMPED):
        raise Refused('unknown original wrapper terminal status')
    child.terminal = {'code': info.si_code, 'status': info.si_status}
    record({'type': 'R-terminal', 'pid': child.pid, **child.terminal})
    retire_authority(child, record)
    # Mask our deadline only across the nonblocking reap/status assignment.
    mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGALRM})
    try:
        pid, raw = os.waitpid(child.pid, os.WNOHANG)
        if pid != child.pid:
            raise Refused('original wrapper reap not confirmed')
        child.raw_status, child.reaped = raw, True
        child.reaped_at = time.monotonic()
    finally:
        signal.pthread_sigmask(signal.SIG_SETMASK, mask)
    record({'type': 'R-reap', 'pid': child.pid, 'raw_status': child.raw_status,
            'reaped_at': child.reaped_at})
    expected = info.si_status if info.si_code == os.CLD_EXITED else -info.si_status
    if os.waitstatus_to_exitcode(child.raw_status) != expected:
        raise Refused('wrapper peek/reap mismatch')
    return True


def emergency_wrapper_signal(child, record):
    if child.reaped or child.retired or not child.signal_authority or child.pidfd is None:
        raise Refused('no live original R signal authority')
    child.intervention = True  # Even a racing ESRCH cannot become success.
    record({'type': 'R-emergency-disposal', 'pid': child.pid, 'product_pass': False,
            'recursive_teardown': False})
    signal.pidfd_send_signal(child.pidfd, signal.SIGKILL, None, 0)


def monitor_fixed(child, readfd, anchor, output, record):
    """Normal R deadline +28; every failure is handled by the same +30 disposal."""
    if child.setup_error is not None:
        raise Refused('original R pidfd acquisition failed: ' + child.setup_error)
    eof = False
    while time.monotonic() < anchor + WRAPPER_NORMAL_SECONDS:
        if readfd in select.select([readfd], [], [], 0.01)[0]:
            data = os.read(readfd, 4096)
            if not data:
                eof = True
            room = MAX_COMMAND_OUTPUT - len(output)
            output.extend(data[:room])
            if len(data) > room:
                raise Refused('command output limit')
        if not child.reaped:
            peek_reap_command(child, record)
        if child.reaped and eof:
            return (child.terminal == {'code': os.CLD_EXITED, 'status': 0}
                    and child.reaped_at < anchor + WRAPPER_NORMAL_SECONDS
                    and not child.intervention)
    raise Refused('R normal allowance ended at shared anchor+28')


def dispose_wrapper(child, readfd, anchor, output, record):
    """No unwind until bounded original-R disposal/confirmation, or explicit unknown."""
    if child is None:
        return True
    confirmed = child.reaped
    try:
        if not confirmed and time.monotonic() < anchor + TOTAL_SECONDS:
            confirmed = peek_reap_command(child, record)
            if not confirmed and child.pidfd is not None and child.signal_authority:
                try:
                    emergency_wrapper_signal(child, record)
                except OSError as exc:
                    record({'type': 'R-signal-error', 'reason': str(exc)})
            # No pidfd means ONLY original-unreaped wait observation, never numeric kill.
        while not confirmed and time.monotonic() < anchor + TOTAL_SECONDS:
            if readfd is not None:
                try:
                    ready = readfd in select.select([readfd], [], [], 0.01)[0]
                    if not ready:
                        confirmed = peek_reap_command(child, record)
                        continue
                    data = os.read(readfd, 4096)
                    output.extend(data[:max(0, MAX_COMMAND_OUTPUT - len(output))])
                except OSError as exc:
                    record({'type': 'R-disposal-output-error', 'reason': str(exc)})
                    readfd = None  # A bad output descriptor does not skip original wait.
            confirmed = peek_reap_command(child, record)
            if not confirmed:
                select.select([], [], [], min(0.01, max(0, anchor + TOTAL_SECONDS - time.monotonic())))
    except BaseException as exc:
        record({'type': 'R-confirmation-error', 'reason': str(exc)})
    finally:
        if not child.retired:
            try:
                retire_authority(child, record)
            except BaseException as exc:
                record({'type': 'R-retire-error', 'reason': str(exc)})
        confirmed = bool(child.reaped and child.reaped_at is not None
                         and child.reaped_at < anchor + TOTAL_SECONDS)
        record({'type': 'R-disposal-final', 'confirmed': confirmed, 'reaped': child.reaped,
                'raw_status': child.raw_status, 'terminal': child.terminal,
                'intervention': child.intervention,
                'unknown': None if confirmed else 'original R exit/reap unconfirmed by shared +30',
                'O_N_teardown_proved_by_R': False})
    return confirmed


def review_gate():
    raise Refused('source-only review: runtime CLI disabled pending main review of revised disposal')


def check_nonroot_records(output, owner_text, before, anchor):
    """Only corroborates non-root records; never labels them root-owned O wait status."""
    command_lines = [json.loads(line) for line in output.decode('utf8').splitlines() if line]
    commands = [e for e in command_lines if e.get('type') == 'kernel-preflight-command']
    events = [json.loads(line) for line in owner_text.splitlines() if line]
    owners = [e for e in events if e.get('type') == 'preflight-owner-before']
    terminals = [e for e in events if e.get('type') == 'direct-terminal' and e.get('role') == 'N']
    reaps = [e for e in events if e.get('type') == 'direct-reap' and e.get('role') == 'N']
    finals = [e for e in events if e.get('type') == 'owner-final']
    proofs = [e for e in events if e.get('type') == 'kernel-preflight-checks']
    if any(len(group) != 1 for group in (commands, owners, terminals, reaps, finals, proofs)):
        raise Refused('missing/ambiguous O or N records')
    for event in (commands[0], terminals[0], reaps[0], finals[0]):
        if not anchor <= event.get('monotonic', -1) < anchor + OWNER_SECONDS:
            raise Refused('O completion/N proof or sole reap outside shared +26')
    if not anchor <= proofs[0].get('monotonic', -1) < anchor + PROOF_SECONDS:
        raise Refused('kernel proof outside shared +22')
    if any(any(word in e.get('type', '') for word in ('failure', 'failsafe', 'unknown', 'error'))
           for e in events):
        raise Refused('non-root intervention/unknown/error is never success')
    identity = owners[0]['identity']
    if (any(identity.get(key) != 1001 for key in ('uid', 'euid', 'gid', 'egid'))
            or any(identity['namespaces'][name] != before['scope']['namespaces'][name]
                   for name in ('user', 'mnt', 'pid'))
            or identity.get('uid_map') != before['scope']['uid_map']
            or identity.get('gid_map') != before['scope']['gid_map']
            or not commands[0].get('ok') or commands[0].get('product_pass') is not False
            or terminals[0].get('code') != os.CLD_EXITED or terminals[0].get('status') != 0
            or reaps[0].get('raw_status') != 0 or reaps[0].get('exit_code') != 0
            or terminals[0].get('pid') != reaps[0].get('pid')
            or not finals[0].get('ok') or not finals[0].get('original_child_reaped')):
        raise Refused('non-root identity or original N terminal/reap mismatch')
    return {'O_status_authority': 'runuser-mediated command status, not root waitid(O)',
            'N_status_authority': 'O original pidfd/WNOWAIT/sole-reap records',
            'O_identity': identity, 'N_terminal': terminals[0], 'N_reap': reaps[0]}


def run_reviewed_path():
    """One fixed normal attempt, disabled; all launched-R paths share disposal."""
    review_gate()
    sole_parent_gate()
    sources = verify_sources()
    before = snapshot()
    if before['uid1001_processes']:
        raise Refused('unrelated UID1001 process exists; no launch')
    prepare_fresh()
    slot, readfd, writefd = OriginalSlot(), None, None
    output, errors = bytearray(), []
    normal = confirmed = False
    anchor = None
    with open(ATTEMPT / 'launcher.jsonl', 'x', encoding='utf8') as log:
        def record(event):
            # Evidence errors are failures, never an exception bypass of disposal.
            try:
                log.write(json.dumps({'monotonic': time.monotonic(), **event}, sort_keys=True) + '\n')
                log.flush()
            except BaseException as exc:
                if not errors:
                    errors.append('launcher evidence sink: ' + str(exc)[:512])
        record({'type': 'baseline', 'snapshot': before, 'sources': sources, 'command': COMMAND})
        previous_handler = signal.getsignal(signal.SIGALRM)
        signal.signal(signal.SIGALRM, root_deadline)
        try:
            readfd, writefd = os.pipe2(os.O_CLOEXEC | os.O_NONBLOCK)
            os.set_blocking(writefd, True)
            anchor = time.monotonic()
            signal.setitimer(signal.ITIMER_REAL, WRAPPER_NORMAL_SECONDS)
            write_anchor(anchor)
            if errors:
                raise Refused(errors[0])
            child = spawn_fixed(writefd, slot)
            os.close(writefd)
            writefd = None
            record({'type': 'original-direct-wrapper', 'role': 'R/runuser', 'pid': child.pid,
                    'pidfd_acquired_from_original_unreaped_child': child.pidfd is not None,
                    'setup_error': child.setup_error})
            normal = monitor_fixed(child, readfd, anchor, output, record)
        except BaseException as exc:
            errors.append(type(exc).__name__ + ': ' + str(exc)[:512])
            record({'type': 'launcher-failure', 'error_type': type(exc).__name__, 'reason': str(exc)[:1024]})
        finally:
            # Slot survives failures after spawn, including pidfd acquisition and mask restore.
            # Never reset the anchor, extend to32s, or substitute authority over O/N.
            child = slot.child
            try:
                if anchor is not None:
                    try:
                        left = anchor + TOTAL_SECONDS - time.monotonic()
                        if left > 0:
                            signal.setitimer(signal.ITIMER_REAL, left)
                    except BaseException as exc:
                        errors.append('final alarm rearm: ' + str(exc)[:512])
                    finally:
                        confirmed = dispose_wrapper(child, readfd, anchor, output, record)
            finally:
                # Only after bounded original disposal; close outputs even on UNKNOWN.
                for fd in (writefd, readfd):
                    if fd is not None:
                        try:
                            os.close(fd)
                        except BaseException as exc:
                            errors.append('output descriptor close: ' + str(exc))
        try:
            record({'type': 'command-observation', 'output': output.decode('utf8', errors='replace'),
                    'normal': normal, 'confirmed': confirmed})
            if anchor is None or time.monotonic() >= anchor + TOTAL_SECONDS:
                raise Refused('final observer unavailable within total30; no secondary clean claim')
            # SAME root observer, bounded by remaining shared30 timer. Census is secondary.
            after = snapshot(expected=before['scope'])
            record({'type': 'final', 'snapshot': after})
            compare_snapshots(before, after)
            if not normal or not confirmed or child is None or child.intervention or errors:
                raise Refused('wrapper failure/intervention/unknown; O/N not inferred disposed')
            evidence = check_nonroot_records(output, bounded_text(EVIDENCE / 'owner.jsonl', 65536), before, anchor)
            if time.monotonic() >= anchor + TOTAL_SECONDS:
                raise Refused('final evidence deadline')
            record({'type': 'kernel-only-evidence', 'product_pass': False, 'evidence': evidence})
        except BaseException as exc:
            errors.append(type(exc).__name__ + ': ' + str(exc)[:512])
        finally:
            signal.setitimer(signal.ITIMER_REAL, 0)
            signal.signal(signal.SIGALRM, previous_handler)
        ok = bool(normal and confirmed and not errors and child and not child.intervention)
        record({'type': 'launcher-final', 'ok': ok, 'product_pass': False, 'errors': errors[:8],
                'R_reaped': bool(child and child.reaped),
                'R_raw_status': child.raw_status if child else None,
                'O_N_status': 'verified non-root records' if ok else 'not confirmed; no further execution'})
        return ok and not errors


def sole_parent_gate():
    if (len(list(Path('/proc/self/task').iterdir())) != 1
            or signal.getsignal(signal.SIGCHLD) != signal.SIG_DFL
            or signal.getitimer(signal.ITIMER_REAL) != (0.0, 0.0)):
        raise Refused('single-threaded sole parent/default SIGCHLD/no inherited timer required')


def root_deadline(*_):
    raise Refused('root fixed absolute deadline')


def write_anchor(anchor):
    # Root-generated data only. Non-root cannot replace it in root-owned ATTEMPT.
    with open(ATTEMPT / 'kernel-anchor.json', 'x', encoding='utf8') as stream:
        stream.write(json.dumps({'monotonic_anchor': anchor}) + '\n')
        stream.flush()
    os.chmod(ATTEMPT / 'kernel-anchor.json', 0o444)


def plan():
    return {'source_review_only': True, 'runtime_enabled': False, 'command': COMMAND,
            'observer': 'one unchanged root process; self namespace/maps/PID/start before and after',
            'source': str(SOURCE), 'pinned': PINNED,
            'shared_anchor_cutoffs_seconds': [22, 24, 26, 28, 30],
            'product_default_cutoffs_seconds': [26, 28, 30],
            'R_authority': 'original unreaped direct child -> retained pidfd -> retire -> sole reap',
            'unresolved': ['main source review before enabling one normal kernel-only attempt',
                           'host/runtime assumptions remain untested; current project transfer blocked']}


if __name__ == '__main__':
    # Source-only CLI: no --run, no preparation/metadata read, no spawn.
    print(json.dumps(plan(), sort_keys=True))

