    "composition-process-controls", "composition-processes",
    "composition-reconciliation", "composition-preview-revocation",
)
CASE_SECONDS = 30
PROOF_SECONDS = 26
INNER_SECONDS = 28  # Last two seconds belong to O's confirmation/reap of N.
PREFLIGHT_PROOF_SECONDS = 22
PREFLIGHT_INNER_SECONDS = 24
PREFLIGHT_OWNER_SECONDS = 26


def envelope_budget(preflight):
    # Only two fixed modes; never accept a caller-selected duration.
    return ((PREFLIGHT_PROOF_SECONDS, PREFLIGHT_INNER_SECONDS, PREFLIGHT_OWNER_SECONDS)
            if preflight else (PROOF_SECONDS, INNER_SECONDS, CASE_SECONDS))


CAMPAIGN_SECONDS = 180
MAX_LIVE = 32
MAX_INSTANCES = 96
OUTPUT_BYTES = 2 * 1024 * 1024
RESERVED_STATUS_BYTES = 4096
UID = GID = 1001
PROFILE = "freedom-appimage-qualification"
FROZEN_BACKEND = "e831a3056a5d6c5d70f87aa7da5fa69bce62467c38cde9f764773209c48d3075"


class Refused(RuntimeError):
    pass


# Explicit mountinfo per-mount option -> Linux MS_* mapping. Never pass ST_*
# statvfs bits to mount(): e.g. ST_RELATIME=4096, MS_RELATIME=1<<21.
MS_BIND, MS_REMOUNT, MS_RDONLY = 4096, 32, 1
MOUNT_OPTION_FLAGS = {"ro": 1, "rw": 0, "nosuid": 2, "nodev": 4,
                      "noexec": 8, "nosymfollow": 256, "noatime": 1024,
                      "nodiratime": 2048, "relatime": 1 << 21,
                      "strictatime": 1 << 24}


def mount_flags(options):
    options = set(options)
    if (options - MOUNT_OPTION_FLAGS.keys() or len(options & {"ro", "rw"}) != 1
            or len(options & {"noatime", "relatime", "strictatime"}) > 1):
        raise Refused("unknown or ambiguous per-mount options: " + repr(sorted(options)))
    flags = 0
    for option in options:
        flags |= MOUNT_OPTION_FLAGS[option]
    # mountinfo omits strictatime: absence of noatime/relatime means strict.
    # Specify it explicitly, rather than allowing mount(2)'s relatime default.
    if not options & {"noatime", "relatime"}:
        flags |= MOUNT_OPTION_FLAGS["strictatime"]
    return flags


def parse_mount_metadata(fdinfo, mountinfo):
    ids = [line.split()[1:] for line in fdinfo.splitlines() if line.startswith("mnt_id:")]
    if len(ids) != 1 or len(ids[0]) != 1 or not ids[0][0].isdigit():
        raise Refused("missing/ambiguous retained fd mount ID")
    mount_id = int(ids[0][0])
    matches = []
    for line in mountinfo.splitlines():
        fields = line.split()
        if fields and fields[0] == str(mount_id):
            try:
                separator = fields.index("-")
                if separator < 6 or len(fields) != separator + 4:
                    raise ValueError("mountinfo shape")
                options = fields[5].split(",")
                mount_flags(options)
                matches.append({"mount_id": mount_id, "mountpoint_escaped": fields[4],
                                "filesystem": fields[separator + 1],
                                "options": options, "super_options": fields[separator + 3].split(",")})
            except (ValueError, IndexError) as exc:
                raise Refused("invalid retained mount metadata") from exc
    if len(matches) != 1:
        raise Refused("retained mount ID missing or ambiguous in mountinfo")
    return matches[0]


def preserved_plan(preserved):
    """Pure lexical plan. Canonical filesystem validation occurs before any mount."""
    roots = {}
    for directory, writable in preserved:
        path = Path(directory)
        if (type(writable) is not bool or not path.is_absolute() or str(path) != directory
                or ".." in path.parts or directory in ("/", "/tmp", "/proc", "/dev", "/dev/shm")
                or path.is_relative_to("/proc") or path.is_relative_to("/dev")):
            raise Refused("invalid or infrastructure-overlapping preserved root")
        if directory in roots:
            if writable or roots[directory]:
                raise Refused("duplicate/ambiguous writable preserved root")
            continue  # Identical readonly roots are one bind, not stacked mounts.
        roots[directory] = writable
    for left in roots:
        for right in roots:
            if left != right and Path(left).is_relative_to(right):
                # Also refuse RO/RO nesting: no mkdir below a readonly ancestor.
                raise Refused("nested preserved roots: " + right + " / " + left)
    return sorted(roots.items())


def canonical_preserved(preserved):
    planned = preserved_plan(preserved)
    for directory, _ in planned:
        if str(Path(directory).resolve(strict=True)) != directory or not Path(directory).is_dir():
            raise Refused("preserved root must be an existing canonical directory")
    return planned


class Phase(enum.Enum):
    PREPARED = "prepared"
    OWNED = "owned-before-release"
    RELEASED = "released"
    IDENTITY = "real-main-identity-verified"
    LIVE = "fixture-held-live"
    ACTION = "action-authorized"
    OBSERVED = "product-exits-observed"
    FAILED = "failed-or-uncertain"


@dataclasses.dataclass
class CaseState:
    case: str
    started: float
    phase: Phase = Phase.PREPARED
    output_bytes: int = 0
    fixture_anchor: float | None = None
    expected: set = dataclasses.field(default_factory=set)
    exits: set = dataclasses.field(default_factory=set)
    failures: list = dataclasses.field(default_factory=list)

    def move(self, before, after):
        if self.phase is not before:
            raise Refused(f"phase {self.phase.value}; expected {before.value}")
        self.phase = after

    def account(self, size):
        self.output_bytes += size
        if self.output_bytes > OUTPUT_BYTES - RESERVED_STATUS_BYTES:
            self.fail("combined output limit")
            raise Refused("combined output limit")

    def fail(self, reason):
        self.failures.append(reason)
        self.phase = Phase.FAILED

    def fixture(self, anchor, now, roles):
        if self.phase is not Phase.IDENTITY or self.case == "browser-idle-quit":
            raise Refused("unexpected fixture")
        if not 0 <= now - anchor < 4 or set(roles) != {"I", "C", "E"}:
            raise Refused("fixture identity/anchor incomplete or too old")
        self.fixture_anchor = anchor
        self.expected.update(roles)
        self.phase = Phase.LIVE

    def action(self, now):
        if now >= self.started + PROOF_SECONDS:
            raise Refused("proof deadline")
        needed = Phase.IDENTITY if self.case == "browser-idle-quit" else Phase.LIVE
        if self.phase is not needed:
            raise Refused("action before identity/live gate")
        if self.fixture_anchor is not None and now >= self.fixture_anchor + 4:
            raise Refused("insufficient margin before independent 15-second expiry")
        self.phase = Phase.ACTION

    def observe_exit(self, role, now):
        if self.phase is not Phase.ACTION or role not in self.expected:
            self.fail(f"unexpected owned exit: {role}")
            return
        if self.fixture_anchor is not None and now >= self.fixture_anchor + 12:
            self.fail("exit too close to fixture expiry; no product teardown credit")
            return
        self.exits.add(role)

    def prove(self, now):
        if (self.phase is not Phase.ACTION or now >= self.started + PROOF_SECONDS
                or self.exits != self.expected or self.failures):
            raise Refused("incomplete product exit proof")
        self.phase = Phase.OBSERVED


@dataclasses.dataclass(frozen=True)
class Identity:
    pid: int                 # PID in the observer's current namespace, NOT payload getpid().
    start: str
    pid_namespace: str
    executable: str


@dataclasses.dataclass
class Owned:
    role: str
    pid: int
    pidfd: int | None
    original_owner: bool
    released: bool = False
    terminal: dict | None = None
    reaped: bool = False


class Registry:
    """Only real-parent gated registration confers signal authority here."""
    def __init__(self, kernel):
        self.kernel = kernel
        self.items = {}
        self.observed = set()

    def register_direct(self, role, pid, gate_closed, sole_unreaped_owner):
        if pid <= 0 or not gate_closed or not sole_unreaped_owner:
            raise Refused("direct ownership not established")
        item = self.items.get(role)
        if item is None:
            item = self.track_direct(role, pid)
        if item.pid != pid or item.pidfd is not None or item.reaped:
            raise Refused("duplicate or invalid registration")
        item.pidfd = self.kernel.pidfd_open(pid)
        return item

    def track_direct(self, role, pid):
        if role in self.items or pid <= 0:
            raise Refused("duplicate original child")
        item = Owned(role, pid, None, True)
        self.items[role] = item
        return item

    def release(self, role):
        item = self.items[role]
        if item.released or item.pidfd is None or self.kernel.exited(item.pidfd):
            raise Refused("child exited before release")
        item.released = True

    def signal_owned(self, role, sig):
        item = self.items[role]
        if not item.original_owner or item.pidfd is None or item.reaped:
            raise Refused("observation is not signal authority")
        if not self.kernel.exited(item.pidfd):
            self.kernel.pidfd_signal(item.pidfd, sig)

    def observe(self, identities, direct_roles):
        """Thresholds are observed counts, explicitly not resource containment."""
        keys = {(i.pid, i.start, i.pid_namespace) for i in identities}
        self.observed.update(keys)
        if len(keys) + direct_roles > MAX_LIVE or len(self.observed) + direct_roles > MAX_INSTANCES:
            raise Refused("observed process threshold")


def terminal_status(item, record):
    """Peek only the original unreaped direct child; never reacquire a PID handle."""
    if not item.original_owner or item.reaped:
        raise Refused("terminal status without unreaped direct ownership")
    if item.terminal is None:
        status = os.waitid(os.P_PID, item.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT)
        if status is None:
            return None
        if status.si_pid != item.pid or status.si_code not in (os.CLD_EXITED, os.CLD_KILLED, os.CLD_DUMPED):
            raise Refused("unknown direct terminal status")
        item.terminal = {"code": status.si_code, "status": status.si_status}
        record({"type": "direct-terminal", "role": item.role, "pid": item.pid,
                **item.terminal})
    return item.terminal


def confirm_reap(item, deadline, record):
    """No signal or PID lookup. Sole-owner WNOHANG polling also covers no-pidfd failure."""
    try:
        while time.monotonic() < deadline:
            status = terminal_status(item, record)
            if status is not None:
                pid, raw = os.waitpid(item.pid, os.WNOHANG)
                if pid != item.pid:
                    raise Refused("terminal child was not reaped by original owner")
                item.reaped = True
                record({"type": "direct-reap", "role": item.role, "pid": pid,
                        "raw_status": raw, "exit_code": os.waitstatus_to_exitcode(raw)})
                expected = status["status"] if status["code"] == os.CLD_EXITED else -status["status"]
                if os.waitstatus_to_exitcode(raw) != expected:
                    raise Refused("peek/reap status mismatch")
                return True
            select.select([], [], [], min(0.01, max(0, deadline - time.monotonic())))
    except (OSError, Refused) as exc:
        record({"type": "direct-unknown", "role": item.role, "reason": str(exc)[:256]})
        return False
    record({"type": "direct-unknown", "role": item.role, "reason": "confirmation deadline"})
    return False


def digest(path):
    h = hashlib.sha256()
    with open(path, "rb") as stream:
        for part in iter(lambda: stream.read(1024 * 1024), b""):
            h.update(part)
    return h.hexdigest()


def regular(path):
    p = Path(path)
    s = p.lstat()
    if not stat.S_ISREG(s.st_mode) or s.st_mode & (stat.S_ISUID | stat.S_ISGID):
        raise Refused(f"not an ordinary regular file: {p}")
    return str(p.resolve(strict=True))


def validate_manifest(m, case):
    required = {"app", "app_sha256", "asar", "asar_sha256", "node", "node_sha256",
                "bridge", "bridge_sha256", "backend_sha256", "source_head",
                "fixture_binding", "composition_binding"}
