    if case != "browser-idle-quit":
        raise Refused("current fixture/composition binding not implemented; no guessed API")
    if m["fixture_binding"] is not None or m["composition_binding"] is not None:
        raise Refused("no arbitrary binding/program accepted")
    for key in ("app", "asar", "node", "bridge"):
