def emit(fd, event):
    data = (json.dumps(event, separators=(",", ":")) + "\n").encode()
    view = memoryview(data)
    while view:
        view = view[os.write(fd, view):]


class Kernel:
    def __init__(self):
        import ctypes
        self.ctypes = ctypes
        self.libc = ctypes.CDLL(None, use_errno=True)
        self.libc.prctl.argtypes = [ctypes.c_int, ctypes.c_ulong, ctypes.c_ulong,
                                    ctypes.c_ulong, ctypes.c_ulong]
        self.libc.mount.argtypes = [ctypes.c_char_p, ctypes.c_char_p, ctypes.c_char_p,
                                    ctypes.c_ulong, ctypes.c_void_p]

    def check(self, result, what):
        if result != 0:
            raise OSError(self.ctypes.get_errno(), what)

    def pidfd_open(self, pid):
        return os.pidfd_open(pid, 0)

    def pidfd_signal(self, fd, sig):
        signal.pidfd_send_signal(fd, sig, None, 0)

    def exited(self, fd):
        return bool(select.select([fd], [], [], 0)[0])

    def arm_parent(self, parentfd, deadline):
        # Parent pidfd was acquired by the parent for ITSELF before fork.
        # It works even when getppid() is zero across the new PID namespace.
        signal.signal(signal.SIGALRM, lambda *_: os._exit(124))
        signal.setitimer(signal.ITIMER_REAL, max(0.001, deadline - time.monotonic()))
        self.check(self.libc.prctl(1, signal.SIGKILL, 0, 0, 0), "PDEATHSIG")
        if self.exited(parentfd):
            os._exit(125)

    def gate(self, readfd, parentfd, deadline):
        self.arm_parent(parentfd, deadline)
        while True:
            left = deadline - time.monotonic()
            if left <= 0:
                os._exit(124)
            ready = select.select([readfd, parentfd], [], [], min(left, 0.1))[0]
            if parentfd in ready:
                os._exit(125)
            if readfd in ready:
                if os.read(readfd, 1) != b"G":
                    os._exit(125)
                if self.exited(parentfd):
                    os._exit(125)
                return

    def namespaces(self):
        # Namespace creation affects only this disposable owner and its future children.
        # PID namespace takes effect on the FIRST subsequent fork.
        flags = 0x10000000 | 0x20000000 | 0x00020000 | 0x40000000 | 0x08000000 | 0x04000000
        self.check(self.libc.unshare(flags), "unshare user,pid,mount,net,ipc,uts")
        for name, value in (("setgroups", "deny\n"), ("uid_map", "1001 1001 1\n"),
                            ("gid_map", "1001 1001 1\n")):
            with open("/proc/self/" + name, "w", encoding="ascii") as out:
                out.write(value)
        if os.getuid() != UID or os.getgid() != GID:
            raise Refused("namespace mapping changed test UID/GID")

    def mount_metadata(self, fd):
        return parse_mount_metadata(Path(f"/proc/self/fdinfo/{fd}").read_text(),
                                    Path("/proc/self/mountinfo").read_text())

    def target_mount_metadata(self, directory):
        fd = os.open(directory, os.O_PATH | os.O_DIRECTORY | os.O_NOFOLLOW)
        try:
            return self.mount_metadata(fd)
        finally:
            os.close(fd)

    def bind_preserved(self, directory, writable, fd, source_meta, record):
        source_flags = mount_flags(source_meta["options"])
        target = os.fsencode(directory)
        record({"type": "mount-options", "stage": "source", "path": directory,
                "writable": writable, "metadata": source_meta})
        self.check(self.libc.mount(os.fsencode(f"/proc/self/fd/{fd}"), target,
                                   None, MS_BIND, None), "preserved bind")
        bound = self.target_mount_metadata(directory)
        record({"type": "mount-options", "stage": "bound", "path": directory, "metadata": bound})
        if mount_flags(bound["options"]) != source_flags:
            raise Refused("bind did not preserve inherited per-mount flags")
        if not writable:
            flags = MS_BIND | MS_REMOUNT | source_flags | MS_RDONLY
            record({"type": "mount-remount-request", "path": directory, "flags": flags})
            self.check(self.libc.mount(None, target, None, flags, None), "read-only input bind")
            after = self.target_mount_metadata(directory)
            record({"type": "mount-options", "stage": "readonly", "path": directory, "metadata": after})
            if (mount_flags(after["options"]) != source_flags | MS_RDONLY
                    or after["mount_id"] != bound["mount_id"]
                    or after["super_options"] != bound["super_options"]):
                raise Refused("readonly remount changed inherited restrictions/atime/superblock")

    def preserve_mounts(self, preserved, record):
        saved = []
        try:
            for directory, writable in preserved:
                fd = os.open(directory, os.O_PATH | os.O_DIRECTORY | os.O_NOFOLLOW)
                saved.append((directory, writable, fd, None))
                metadata = self.mount_metadata(fd)
                saved[-1] = (directory, writable, fd, metadata)
                record({"type": "mount-options", "stage": "source-before-cover", "path": directory,
                        "writable": writable, "metadata": metadata})
                if writable and (mount_flags(metadata["options"]) & MS_RDONLY
                                 or "ro" in metadata["super_options"]):
                    raise Refused("writable evidence source is readonly; no relaxation")
            self.check(self.libc.mount(b"tmpfs", b"/tmp", b"tmpfs", 2 | 4,
                                      b"size=134217728,mode=1777"), "private tmp")
            self.check(self.libc.mount(b"tmpfs", b"/dev/shm", b"tmpfs", 2 | 4,
                                      b"size=67108864,mode=1777"), "private shm")
            for directory, writable, fd, metadata in saved:
                Path(directory).mkdir(parents=True, exist_ok=True)
                self.bind_preserved(directory, writable, fd, metadata, record)
        finally:
            for _, _, fd, _ in saved:
                os.close(fd)

    def setup_init(self, parentfd, deadline, preserved, record):
        # Reject all overlap/alias ambiguity BEFORE even propagation/proc changes.
        preserved = canonical_preserved(preserved)
        self.check(self.libc.mount(None, b"/", None, 16384 | (1 << 18), None),
                   "private mount propagation")
        self.check(self.libc.mount(b"proc", b"/proc", b"proc", 2 | 4 | 8, None),
                   "private PID namespace proc")
        if os.getpid() != 1 or os.getuid() != UID:
            raise Refused("not ordinary-user test namespace init")
        # Preserve every declared input readonly, including inputs outside /tmp.
        self.preserve_mounts(preserved, record)
        # Only loopback in the fresh network namespace; no host interfaces/routes.
        import fcntl
        import struct
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
            req = struct.pack("16sH14s", b"lo", 0, b"")
            got = fcntl.ioctl(sock.fileno(), 0x8913, req)
            flags = struct.unpack("16sH14s", got)[1]
            fcntl.ioctl(sock.fileno(), 0x8914, struct.pack("16sH14s", b"lo", flags | 1, b""))
        self.check(self.libc.prctl(38, 1, 0, 0, 0), "no_new_privs")
        # Drop capabilities, then REARM/check parent link after that credential transition.
        class Header(self.ctypes.Structure):
            _fields_ = [("version", self.ctypes.c_uint), ("pid", self.ctypes.c_int)]
        class Caps(self.ctypes.Structure):
            _fields_ = [("effective", self.ctypes.c_uint), ("permitted", self.ctypes.c_uint),
                        ("inheritable", self.ctypes.c_uint)]
        header = Header(0x20080522, 0)
        caps = (Caps * 2)()
        self.check(self.libc.capset(self.ctypes.byref(header), self.ctypes.byref(caps)), "capset")
        self.arm_parent(parentfd, deadline)


def spawn_gated(kernel, registry, role, argv, environment, deadline, stdin=None, stdout=None):
    """No polling/reaper thread; parent retains sole wait ownership until registered."""
    gate_r, gate_w = os.pipe2(os.O_CLOEXEC)
    parentfd = kernel.pidfd_open(os.getpid())
    out_r, out_w = os.pipe2(os.O_CLOEXEC | os.O_NONBLOCK)
    pid = os.fork()
    if pid == 0:
        try:
            os.close(gate_w)
            os.close(out_r)
            kernel.gate(gate_r, parentfd, deadline)
            os.close(gate_r)
            os.set_blocking(out_w, True)
            os.dup2(out_w, 2)
            os.dup2(out_w if stdout is None else stdout, 1)
            if stdin is None:
                null = os.open("/dev/null", os.O_RDONLY)
                os.dup2(null, 0)
                os.close(null)
            else:
                os.dup2(stdin, 0)
            # ITIMER_REAL survives exec on Linux. This is supplemental only: the
            # owned namespace-init deadline is the enclosing fail-safe. Parent pidfd
            # is CLOEXEC; PDEATHSIG remains for ordinary non-setid executables.
            os.execve(argv[0], argv, environment)
        except BaseException:
            os._exit(126)
    registry.track_direct(role, pid)  # Retain the child even if pidfd creation fails.
    os.close(gate_r)
    os.close(out_w)
    os.close(parentfd)
    try:
        registry.register_direct(role, pid, True, True)
        registry.release(role)
        if os.write(gate_w, b"G") != 1:
            raise Refused("short gate write")
        return out_r
    except BaseException:
        os.close(out_r)
        raise
    finally:
        # EOF before G makes an unregistered child self-exit; never numeric cleanup.
        os.close(gate_w)


class ProcessDiagnostic(Refused):
    def __init__(self, pid, kind, state=None, start=None):
        self.pid, self.kind, self.state, self.start = pid, kind, state, start
        super().__init__(f"process {pid}: {kind}; state={state}; start={start}")


def registered_observation_exit(observation, requested, observed_fds, kernel):
    if not requested or observation.kind == "stat-malformed":
        return False
    return any(key[0] == observation.pid
               and (observation.start is None or key[1] == observation.start)
               and kernel.exited(fd) for key, fd in observed_fds.items())


def process_stat(pid):
    root = Path("/proc") / str(pid)
    try:
        text = (root / "stat").read_text()
    except OSError as exc:
        raise ProcessDiagnostic(pid, "stat-unavailable") from exc
    fields = text[text.rfind(")") + 2:].split()
    if text.rfind(")") < 0 or len(fields) < 20 or not fields[19].isdigit():
        raise ProcessDiagnostic(pid, "stat-malformed")
    return fields[0], fields[19]


def process_identity(pid):
    root = Path("/proc") / str(pid)
    state, start = process_stat(pid)
    if state in ("Z", "X", "x"):
        # Zombie is exited-unreaped, but this observation is NOT pidfd exit proof.
        raise ProcessDiagnostic(pid, "zombie-exited-unreaped" if state == "Z" else "dead-state",
                                state, start)
    try:
        namespace = os.readlink(root / "ns/pid")
    except OSError as exc:
        raise ProcessDiagnostic(pid, "pid-namespace-unavailable", state, start) from exc
    try:
        executable = os.readlink(root / "exe")
    except OSError as exc:
        # Re-read stat only to distinguish a newly zombified process, not to prove exit.
        try:
            after_state, after_start = process_stat(pid)
        except ProcessDiagnostic:
            after_state, after_start = state, start
        kind = "zombie-exited-unreaped" if after_state == "Z" else "exe-unavailable"
        raise ProcessDiagnostic(pid, kind, after_state, after_start) from exc
    return Identity(pid, start, namespace, executable)


def owned_descendants(root_pid, allow_registered_exit=None, diagnostic=None):
    """Read-only walk anchored in original owned B, not a host process census."""
    result, pending, visited = [], [root_pid], set()
    while pending:
        pid = pending.pop()
        if pid in visited:
            continue
        visited.add(pid)
        try:
            identity = process_identity(pid)
            children = []
            try:
                tasks = list((Path("/proc") / str(pid) / "task").iterdir())
                if not tasks:
                    raise OSError("empty task directory")
            except OSError as exc:
                raise ProcessDiagnostic(pid, "task-directory-unavailable", start=identity.start) from exc
            for task in tasks:
                try:
                    children.extend(int(p) for p in (task / "children").read_text().split())
                except (OSError, ValueError) as exc:
                    raise ProcessDiagnostic(pid, "task-children-unavailable", start=identity.start) from exc
            result.append(identity)
            pending.extend(children)
        except ProcessDiagnostic as exc:
            allowed = bool(allow_registered_exit and allow_registered_exit(exc))
            if allowed and diagnostic is None:
                raise Refused("registered observation loss requires a retained diagnostic") from exc
            if diagnostic:
                diagnostic({"type": "process-diagnostic", "observer_pid": pid,
                            "kind": exc.kind, "state": exc.state, "start": exc.start,
                            "registered_pidfd_exit": allowed, "product_exit_proof": False})
            # A recorded, previously retained pidfd can explain observation loss
            # AFTER the action. Only the separate pidfd loop credits its exit.
            if not allowed:
                raise
    return result


def private_environment(root):
    dirs = {}
    for name in ("home", "cache", "config", "data", "runtime", "tmp", "profile"):
        p = root / name
        p.mkdir(mode=0o700)
        dirs[name] = str(p)
    return {"PATH": "/usr/bin:/bin", "LANG": "C.UTF-8", "HOME": dirs["home"],
            "XDG_CACHE_HOME": dirs["cache"], "XDG_CONFIG_HOME": dirs["config"],
            "XDG_DATA_HOME": dirs["data"], "XDG_RUNTIME_DIR": dirs["runtime"],
            "TMPDIR": dirs["tmp"], "FREEDOM_TEST_MODE": "1",
            "FREEDOM_TEST_USER_DATA": dirs["profile"], "FREEDOM_REQUIRE_BWRAP": "1"}


def run_idle(kernel, manifest, root, events, started):
    """Only fully specified case so far. Running fixture/Stop binding is not guessed."""
    import re
    state = CaseState("browser-idle-quit", started)
    registry = Registry(kernel)
    env = private_environment(root)
    self_fd = kernel.pidfd_open(os.getpid())
    logs = {}
    streams = {}
    buffers = {}
    node_in = None
    exited = set()
    observed_fds = {}
    requested_quit = False

    def record(event):
        event = {"monotonic": time.monotonic(), **event}
        # Account duplicated init+owner JSON records as well as process streams.
        state.account(2 * (len(json.dumps(event).encode()) + 1))
        emit(events, event)
        with open(root / "records.jsonl", "ab") as out:
            out.write((json.dumps(event) + "\n").encode())

    def launch(role, argv, stdin=None):
        fd = spawn_gated(kernel, registry, role, argv, env, started + INNER_SECONDS,
                         stdin=stdin)
        streams[fd] = role
        buffers[role] = b""
        logs[role] = open(root / (role + ".combined.log"), "xb", buffering=0)
        record({"type": "direct-owned", "role": role, "observer_pid": registry.items[role].pid,
                "pid_namespace": os.readlink("/proc/self/ns/pid")})

    try:
        # Fresh mount namespace does not by itself hide old X11 sockets. Use displayfd
        # selection and -nolisten tcp; never attach to an existing display.
        launch("X", ["/usr/bin/Xvfb", "-displayfd", "1", "-screen", "0", "1280x800x24",
                     "-nolisten", "tcp", "-noreset"])
        state.move(Phase.PREPARED, Phase.OWNED)
        state.move(Phase.OWNED, Phase.RELEASED)
        bridge_started = False
        browser_started = False
        identity = False
        action_sent = False
        quit_ack = False
        while time.monotonic() < started + PROOF_SECONDS:
            if kernel.exited(self_fd):
                raise Refused("impossible self identity exit")
            for fd in select.select(list(streams), [], [], 0.05)[0]:
                role = streams[fd]
                data = os.read(fd, 8192)
                if not data:
                    os.close(fd)
                    del streams[fd]
                    continue
                state.account(len(data))
                logs[role].write(data)
                buffers[role] += data
                if len(buffers[role]) > 65536:
                    raise Refused("unterminated output line")
                while b"\n" in buffers[role]:
                    line, buffers[role] = buffers[role].split(b"\n", 1)
                    if role == "X" and not browser_started and re.fullmatch(rb"[0-9]{1,5}", line):
                        env["DISPLAY"] = ":" + line.decode()
                        launch("B", [manifest["app"], "--inspect=127.0.0.1:0"])
                        browser_started = True
                    if role == "B" and not bridge_started:
                        match = re.fullmatch(rb"Debugger listening on (ws://127\.0\.0\.1:[0-9]+/[a-zA-Z0-9-]+)", line)
                        if match:
                            readfd, node_in = os.pipe2(os.O_CLOEXEC)
                            launch("D", [manifest["node"], manifest["bridge"]], stdin=readfd)
                            os.close(readfd)
                            emit(node_in, {"op": "connect", "url": match[1].decode()})
                            bridge_started = True
                    if role == "D" and line.startswith(b"{"):
                        msg = json.loads(line)
                        record({"type": "bridge", "message": msg})
                        if msg.get("type") == "identity":
                            verify_identity(msg["identity"], manifest)
                            identity = True
                            state.move(Phase.RELEASED, Phase.IDENTITY)
                            state.expected = {"B"}
                        elif msg.get("type") == "quit-scheduled":
                            quit_ack = True
                        elif msg.get("type") == "failure":
                            raise Refused("bridge: " + msg["reason"])
            if browser_started and "B" not in exited:
                if not kernel.exited(registry.items["B"].pidfd):
                    def registered_exit(observation):
                        return registered_observation_exit(observation, requested_quit,
                                                           observed_fds, kernel)
                    snapshots = owned_descendants(registry.items["B"].pid, registered_exit, record)
                    # Product subtree includes B; O(owner), N(init), X(display),
                    # D(bridge) are four additional finite roles.
                    registry.observe(snapshots, direct_roles=4)
                    for snapshot in snapshots:
                        if snapshot.pid == registry.items["B"].pid:
                            continue
                        key = (snapshot.pid, snapshot.start, snapshot.pid_namespace)
                        if key not in observed_fds:
                            # Observation ONLY, never signal authority. Identity loss is failure.
                            fd = kernel.pidfd_open(snapshot.pid)
                            after = process_identity(snapshot.pid)
                            if after != snapshot or kernel.exited(fd):
                                os.close(fd)
                                raise Refused("descendant registration changed identity")
                            observed_fds[key] = fd
                            if requested_quit:
                                raise Refused("new product descendant after Quit action")
            if identity and not requested_quit:
                if any(kernel.exited(fd) for fd in observed_fds.values()):
                    raise Refused("observed product exit before selected action")
                state.action(time.monotonic())
                state.expected.update("P:" + str(key) for key in observed_fds)
                record({"type": "action-request", "action": "native-app-quit"})
                emit(node_in, {"op": "app-quit"})
                action_sent = requested_quit = True
            for key, fd in observed_fds.items():
                role = "P:" + str(key)
                if role not in exited and kernel.exited(fd):
                    exited.add(role)
                    state.observe_exit(role, time.monotonic())
                    record({"type": "observed-product-exit", "identity": key})
            for role, item in registry.items.items():
                if role not in exited and kernel.exited(item.pidfd):
                    exited.add(role)
                    status = terminal_status(item, record)
                    if status is None:
                        raise Refused("pidfd readable but direct terminal status unknown: " + role)
                    if role == "B" and identity and action_sent:
                        if status != {"code": os.CLD_EXITED, "status": 0}:
                            raise Refused("browser Quit did not exit normally with code zero")
                        state.observe_exit("B", time.monotonic())
                        continue
                    raise Refused("unexpected owned exit: " + role)
            if quit_ack and "B" in exited and state.exits == state.expected:
                state.prove(time.monotonic())
                record({"type": "product-proof", "case": state.case,
                        "scope": "native Electron app.quit lifecycle; no desktop Quit claim"})
                return True
        raise Refused("proof watchdog expired")
    except BaseException as exc:
        state.fail(str(exc))
        # Reserve an independent bounded failure record if output accounting already failed.
        emit(events, {"type": "failure", "reason": str(exc)[:512]})
        return False
    finally:
        # Any B intervention is failure, even if it subsequently exits.
        if "B" in registry.items and (registry.items["B"].pidfd is None
                                     or not kernel.exited(registry.items["B"].pidfd)):
            emit(events, {"type": "failsafe", "role": "B", "product_pass": False})
        cleanup_errors = []
        for role in ("B", "D", "X"):
            if role in registry.items and registry.items[role].pidfd is not None:
                try:
                    registry.signal_owned(role, signal.SIGKILL)
                except OSError as exc:
                    cleanup_errors.append(f"{role}: {exc}")
        limit = started + INNER_SECONDS
        def cleanup_record(event):
            # Preserve every sole-reap status even after ordinary output accounting fails.
            emit(events, {"monotonic": time.monotonic(), **event})
        for item in registry.items.values():
            if not confirm_reap(item, limit, cleanup_record):
                cleanup_errors.append(f"owned survivor: {item.role}")
            if item.pidfd is not None:
                os.close(item.pidfd)
        for fd in observed_fds.values():
            os.close(fd)
        # Drain retained output/status through EOF within cleanup budget.
        while streams and time.monotonic() < limit:
            for fd in select.select(list(streams), [], [], 0.01)[0]:
                data = os.read(fd, 8192)
                if data:
                    remaining = max(0, OUTPUT_BYTES - RESERVED_STATUS_BYTES - state.output_bytes)
                    logs[streams[fd]].write(data[:remaining])
                    state.output_bytes += len(data[:remaining])
                    if len(data) > remaining and "output limit during final drain" not in cleanup_errors:
                        cleanup_errors.append("output limit during final drain")
                else:
                    os.close(fd)
                    del streams[fd]
        if streams:
            cleanup_errors.append("output descriptors not drained by deadline")
        for fd in streams:
            os.close(fd)
        if node_in is not None:
            os.close(node_in)
        os.close(self_fd)
        for out in logs.values():
            out.close()
        if cleanup_errors:
            raise Refused("; ".join(cleanup_errors))


def verify_identity(i, m):
    if (i.get("uid") != UID or i.get("gid") != GID or not i.get("isPackaged")
            or not i.get("mainLoaded") or not i.get("harnessReady")
            or i.get("appPath") != m["asar"] or i.get("execPath") != m["app"]
            or i.get("asarSha256") != m["asar_sha256"]
            or i.get("backendSha256") != FROZEN_BACKEND
            or i.get("main") != "src/main/index.js"
            or i.get("noSandbox") is not False or i.get("rawArchiveIsFile") is not True
            or not i.get("sandboxPreferences")
            or any(p.get("sandbox") is not True or p.get("nodeIntegration") is not False
                   or p.get("contextIsolation") is not True
                   for p in i["sandboxPreferences"])):
        raise Refused("real packaged identity mismatch")


def campaign_gate(anchor, now):
    if anchor is None or not 0 <= now - anchor <= CAMPAIGN_SECONDS - CASE_SECONDS:
        raise Refused("shared campaign anchor missing or less than 30 seconds remain")


def execute(manifest, case, root, campaign_anchor):
    campaign_gate(campaign_anchor, time.monotonic())
    if os.getuid() != UID or os.geteuid() != UID or os.getgid() != GID:
        raise Refused("run only as existing freedomqual uid/gid 1001")
    if Path("/proc/self/attr/current").read_text().strip().split(" (")[0] != PROFILE:
        raise Refused("existing qualification AppArmor profile required")
    if len(list(Path("/proc/self/task").iterdir())) != 1:
        raise Refused("single-threaded owner required")
    if signal.getsignal(signal.SIGCHLD) == signal.SIG_IGN:
        raise Refused("auto-reaping SIGCHLD disposition forbidden")
    validate_manifest(manifest, case)
    root = Path(root)
    if not root.is_absolute() or str(root.parent.resolve(strict=True)) != str(root.parent):
        raise Refused("evidence parent must be existing canonical absolute path")
    root.mkdir(mode=0o700)  # Existing path, including symlink, is rejected.
    os.chdir(root)
    return run_envelope(Kernel(), manifest, root, time.monotonic())


def run_envelope(kernel, manifest, root, started, preflight_input=None):
    """Actual owner path, injectable only by pure tests; same 30s absolute budget."""
    if preflight_input is not None and manifest is not None:
        raise Refused("kernel preflight must not have a product manifest")
    output_limit = 65536 if preflight_input is not None else OUTPUT_BYTES
    proof_seconds, inner_seconds, owner_seconds = envelope_budget(preflight_input is not None)
    if preflight_input is not None and time.monotonic() >= started + proof_seconds:
        raise Refused("preflight shared proof deadline already expired; no namespace creation")
    registry = Registry(kernel)
    fds = set()
    gate_w = None
    result = False
    finished = False
    clean = True
    with open(root / "owner.jsonl", "xb", buffering=0) as log:
        output = 0
        record_errors = []

        def record(event):
            nonlocal output, clean
            data = (json.dumps({"monotonic": time.monotonic(), **event}) + "\n").encode()
            try:
                if output + len(data) > output_limit:
                    raise Refused("owner evidence limit including reserved statuses")
                if log.write(data) != len(data):
                    raise Refused("short owner evidence write")
                output += len(data)
            except (OSError, Refused) as exc:
                # A failed evidence sink must not skip owned cleanup. The caller
                # gets explicit failure after confirmation, never a successful report.
                clean = False
                if not record_errors:
                    record_errors.append(str(exc))

        def closefd(fd):
            if fd in fds:
                fds.remove(fd)
                os.close(fd)

        def deadline_handler(*_):
            raise Refused("outer deadline")

        signal.signal(signal.SIGALRM, deadline_handler)
        signal.setitimer(signal.ITIMER_REAL, max(0.001, started + inner_seconds - time.monotonic()))
        try:
            parentfd = kernel.pidfd_open(os.getpid())
            fds.add(parentfd)
            owner_before = None
            if preflight_input is not None:
                owner_before = namespace_snapshot()
                record({"type": "preflight-owner-before", "identity": owner_before,
                        "self_pidfd_retained_for_N": parentfd,
                        "self_pidfd_info": Path(f"/proc/self/fdinfo/{parentfd}").read_text()})
            gate_r, gate_w = os.pipe2(os.O_CLOEXEC)
            fds.update((gate_r, gate_w))
            event_r, event_w = os.pipe2(os.O_CLOEXEC | os.O_NONBLOCK)
            fds.update((event_r, event_w))
            kernel.namespaces()
            if preflight_input is not None:
                record({"type": "preflight-owner-after-unshare", "identity": namespace_snapshot()})
            # Do not let the asynchronous owner deadline interrupt fork->original tracking.
            mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGALRM})
            try:
                init_pid = os.fork()  # First fork: actual new namespace init.
                if init_pid != 0:
                    registry.track_direct("N", init_pid)
                else:
                    # Replace O's inherited handler before restoring the signal mask.
                    # Interval timers themselves are not inherited across fork; gate arms N.
                    signal.signal(signal.SIGALRM, lambda *_: os._exit(124))
            finally:
                signal.pthread_sigmask(signal.SIG_SETMASK, mask)
            if init_pid == 0:
                try:
                    os.close(gate_w)
                    os.close(event_r)
                    os.set_blocking(event_w, True)
                    kernel.gate(gate_r, parentfd, started + inner_seconds)
                    os.close(gate_r)
                    ok = namespace_work(kernel, manifest, root, event_w, started,
                                        preflight_input, owner_before, parentfd)
                    emit(event_w, {"type": "finished", "ok": ok})
                    os._exit(0 if ok else 1)
                except BaseException as exc:
                    emit(event_w, {"type": "failure", "reason": str(exc)[:512]})
                    os._exit(1)
            record({"type": "original-child", "role": "N", "host_pid": init_pid})
            closefd(gate_r)
            closefd(event_w)
            item = registry.register_direct("N", init_pid, True, True)
            record({"type": "namespace-owned-before-release", "host_pid": init_pid})
            registry.release("N")
            if os.write(gate_w, b"G") != 1:
                raise Refused("short namespace gate write")
            closefd(gate_w)
            buffer = b""
            eof = False
            while not (kernel.exited(item.pidfd) and eof):
                if time.monotonic() >= started + inner_seconds:
                    raise Refused("inner cleanup deadline; outer confirmation reserved")
                if event_r in select.select([event_r], [], [], 0.01)[0]:
                    data = os.read(event_r, 8192)
                    eof = not data
                    if output + len(data) > output_limit - RESERVED_STATUS_BYTES:
                        raise Refused("owner evidence limit")
                    log.write(data)
                    output += len(data)
                    buffer += data
                    if len(buffer) > 65536:
                        raise Refused("owner event line bound")
                    while b"\n" in buffer:
                        line, buffer = buffer.split(b"\n", 1)
                        msg = json.loads(line)
                        if msg.get("type") == "finished":
                            if finished:
                                raise Refused("duplicate finished event")
                            finished = True
                            result = msg.get("ok") is True
                        elif msg.get("type") in ("failure", "failsafe", "direct-unknown"):
                            clean = False
            if buffer:
                raise Refused("truncated namespace event")
        except BaseException as exc:
            result = False
            record({"type": "owner-failure", "reason": str(exc)[:512]})
        finally:
            # Fixed product +28/+30; fixed preflight +24/+26 on the root's SAME anchor.
            # The only alarm stays active through confirmation; expiration is UNKNOWN.
            try:
                left = started + owner_seconds - time.monotonic()
                if left > 0:
                    signal.setitimer(signal.ITIMER_REAL, left)
                if gate_w is not None:
                    closefd(gate_w)  # No pidfd: EOF/self-expiry only, never numeric signal.
                item = registry.items.get("N")
                if item is not None:
                    try:
                        if left > 0 and item.pidfd is not None and not kernel.exited(item.pidfd):
                            result = False
                            record({"type": "outer-failsafe", "role": "N", "product_pass": False})
                            registry.signal_owned("N", signal.SIGKILL)
                    except OSError as exc:
                        result = False
                        record({"type": "outer-signal-error", "reason": str(exc)[:256]})
                        # ESRCH/failed pidfd signal is not exit evidence; still reap
                        # through original direct ownership with no new signal target.
                    confirmed = confirm_reap(item, started + owner_seconds, record)
                    clean = clean and confirmed
                    result = (result and finished and confirmed and
                              item.terminal == {"code": os.CLD_EXITED, "status": 0})
                else:
                    result = False
                if time.monotonic() >= started + owner_seconds:
                    clean = False
                    record({"type": "owner-unknown", "reason": "outer wall deadline reached"})
            except BaseException as exc:
                clean = result = False
                record({"type": "owner-unknown", "reason": str(exc)[:512]})
            finally:
                # Only now cancel the alarm, after explicit confirmation or recorded unknown.
                if preflight_input is None:
                    signal.setitimer(signal.ITIMER_REAL, 0)
                else:
                    # O retains an independent final expiry through evidence/entry exit.
                    signal.signal(signal.SIGALRM, lambda *_: os._exit(124))
                    signal.setitimer(signal.ITIMER_REAL,
                                     max(0.001, started + owner_seconds - time.monotonic()))
                for item in registry.items.values():
                    if item.pidfd is not None:
                        fds.add(item.pidfd)
                for fd in list(fds):
                    try:
                        closefd(fd)
                    except OSError as exc:
                        clean = False
                        record({"type": "descriptor-failure", "fd": fd, "reason": str(exc)[:256]})
        result = bool(result and clean)
        record({"type": "owner-final", "ok": result,
                "original_child_reaped": bool(registry.items.get("N") and registry.items["N"].reaped)})
        if record_errors:
            raise Refused("owner evidence incomplete after cleanup: " + record_errors[0])
        return result


def namespace_work(kernel, manifest, root, events, started, preflight_input, owner_before, parentfd):
    if preflight_input is None:
        preserved = [(str(Path(manifest[key]).parent), False) for key in ("app", "node", "bridge")]
    else:
        if manifest is not None:
            raise Refused("kernel preflight cannot select product bindings")
        emit(events, {"type": "preflight-N-after-gate", "identity": namespace_snapshot()})
        preserved = [(preflight_input, False)]
    preserved.append((str(root), True))
    inner_seconds = envelope_budget(preflight_input is not None)[1]
    kernel.setup_init(parentfd=parentfd, deadline=started + inner_seconds, preserved=preserved,
                      record=lambda event: emit(events, event))
    emit(events, {"type": "namespace-init", "inner_pid": os.getpid(), "uid": os.getuid(),
                  "namespace": os.readlink("/proc/self/ns/pid")})
    if preflight_input is None:
        return run_idle(kernel, manifest, root, events, started)
    return kernel_preflight_checks(kernel, root, preflight_input, owner_before, events, started)


def namespace_snapshot():
    return {"uid": os.getuid(), "euid": os.geteuid(), "gid": os.getgid(),
            "egid": os.getegid(), "pid_observed_here": os.getpid(),
            "namespaces": {name: os.readlink("/proc/self/ns/" + name)
                           for name in ("pid", "user", "mnt", "net", "ipc", "uts")},
            "uid_map": Path("/proc/self/uid_map").read_text(),
            "gid_map": Path("/proc/self/gid_map").read_text(),
            "profile": Path("/proc/self/attr/current").read_text().strip()}


def kernel_preflight_checks(kernel, root, test_input, owner_before, events, started):
    """Fixed benign N checks only: no program binding, child creation or fault action."""
    import fcntl
    import struct
    identity = namespace_snapshot()
    if any(identity[k] != UID for k in ("uid", "euid", "gid", "egid")) or identity["pid_observed_here"] != 1:
        raise Refused("preflight N is not ordinary uid/gid1001 PID1")
    if any(identity["namespaces"][name] == owner_before["namespaces"][name]
           for name in ("pid", "user", "mnt", "net", "ipc", "uts")):
        raise Refused("preflight namespace not distinct from original O namespace")
    if identity["profile"].split(" (")[0] != PROFILE:
        raise Refused("preflight N profile changed")
    fields = dict(line.split(":", 1) for line in Path("/proc/self/status").read_text().splitlines() if ":" in line)
    status = {name: fields.get(name, "").strip()
              for name in ("NoNewPrivs", "CapInh", "CapPrm", "CapEff", "CapBnd", "CapAmb")}
    if status["NoNewPrivs"] != "1" or any(int(status[name], 16) != 0
                                             for name in ("CapInh", "CapPrm", "CapEff", "CapAmb")):
        raise Refused("preflight capabilities/no_new_privs mismatch")
    mounts = {name: kernel.target_mount_metadata(path) for name, path in
              (("proc", "/proc"), ("tmp", "/tmp"), ("shm", "/dev/shm"),
               ("input", test_input), ("evidence", str(root)))}
    if (mounts["proc"]["filesystem"] != "proc" or Path("/proc/self").readlink() != Path("1")
            or mounts["tmp"]["filesystem"] != "tmpfs" or mounts["shm"]["filesystem"] != "tmpfs"
            or not d_readonly(mounts["input"]) or d_readonly(mounts["evidence"])):
        raise Refused("preflight private mount/view mismatch")
    if list(Path(test_input).iterdir()) or not os.access(root, os.W_OK):
        raise Refused("preflight input not empty or evidence view not writable")
    net_dev = Path("/proc/net/dev").read_text()
    interfaces = sorted(line.split(":", 1)[0].strip() for line in net_dev.splitlines() if ":" in line)
    if interfaces != ["lo"]:
        raise Refused("preflight private network contains non-loopback interface")
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        response = fcntl.ioctl(sock.fileno(), 0x8913, struct.pack("16sH14s", b"lo", 0, b""))
        loopback_flags = struct.unpack("16sH14s", response)[1]
    if loopback_flags & (1 | 8) != (1 | 8):
        raise Refused("preflight loopback not UP/LOOPBACK")
    shm = os.statvfs("/dev/shm")
    report = {"type": "kernel-preflight-checks", "product_pass": False, "identity": identity,
              "monotonic": time.monotonic(),
              "status": status, "mounts": mounts, "input_empty": True,
              "evidence_writable_view": True, "loopback_flags": loopback_flags,
              "interfaces": interfaces, "net_dev": net_dev,
              "net_route": Path("/proc/net/route").read_text(),
              "shm_bytes_observed": shm.f_frsize * shm.f_blocks,
              "shm_bytes_available_observed": shm.f_frsize * shm.f_bavail}
    if time.monotonic() >= started + PREFLIGHT_PROOF_SECONDS:
        raise Refused("kernel preflight proof deadline")
    data = json.dumps(report) + "\n"
    if len(data.encode()) > 32768:
        raise Refused("kernel preflight record bound")
    with open(root / "namespace-check.json", "x", encoding="utf8") as output:
        output.write(data)  # Fixed fresh evidence path only; test-input stays empty.
    emit(events, report)
    return True


def d_readonly(metadata):
    return bool(mount_flags(metadata["options"]) & MS_RDONLY or "ro" in metadata["super_options"])


def preflight_anchor(root):
    # Fixed root-owned data path, not a timeout argument, environment setting or code.
    path = Path(root).parent / 'kernel-anchor.json'
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        metadata = os.fstat(fd)
        if (not stat.S_ISREG(metadata.st_mode) or metadata.st_uid != 0
                or stat.S_IMODE(metadata.st_mode) != 0o444):
            raise Refused('preflight anchor must be root-owned0444 regular data')
        raw = os.read(fd, 1025)
        if len(raw) > 1024:
            raise Refused('preflight anchor byte bound')
        data = json.loads(raw)
    finally:
        os.close(fd)
    if set(data) != {'monotonic_anchor'}:
        raise Refused('no caller-selected deadline fields allowed')
    anchor = data['monotonic_anchor']
    if (type(anchor) not in (int, float) or not math.isfinite(anchor)
            or not 0 <= time.monotonic() - anchor < PREFLIGHT_PROOF_SECONDS):
        raise Refused('missing/future/expired fixed preflight anchor')
    return anchor


def execute_kernel_preflight(root, test_input):
    # No manifest/app identity and no caller-controlled program or callback.
    if (os.getuid(), os.geteuid(), os.getgid(), os.getegid()) != (UID, UID, GID, GID):
        raise Refused("kernel preflight requires freedomqual uid/gid1001")
    if Path("/proc/self/attr/current").read_text().strip().split(" (")[0] != PROFILE:
        raise Refused("existing qualification AppArmor profile required")
    if len(list(Path("/proc/self/task").iterdir())) != 1 or signal.getsignal(signal.SIGCHLD) == signal.SIG_IGN:
        raise Refused("single-threaded sole-reaping owner required")
    root = Path(root)
    anchor = preflight_anchor(root)
    signal.signal(signal.SIGALRM, lambda *_: os._exit(124))
    signal.setitimer(signal.ITIMER_REAL,
                     max(0.001, anchor + PREFLIGHT_OWNER_SECONDS - time.monotonic()))
    canonical_preserved([(test_input, False), (str(root), True)])
    if list(root.iterdir()) or list(Path(test_input).iterdir()):
        raise Refused("preflight requires fresh empty input and evidence")
    os.chdir(root)
    return run_envelope(Kernel(), None, root, anchor, preflight_input=test_input)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--case", choices=CASES, required=True)
    parser.add_argument("--manifest")
    parser.add_argument("--evidence")
    parser.add_argument("--campaign-anchor", type=float)
    parser.add_argument("--run", action="store_true")
    args = parser.parse_args()
    if not args.run:
        print(json.dumps({"case": args.case, "source_only": True, "case_seconds": CASE_SECONDS,
                          "proof_seconds": PROOF_SECONDS, "campaign_seconds": CAMPAIGN_SECONDS,
                          "live_observed_limit": MAX_LIVE, "instances_observed_limit": MAX_INSTANCES,
                          "output_bytes": OUTPUT_BYTES,
                          "idle_protocol_implemented": args.case == "browser-idle-quit",
                          "runtime_ready": False}))
        return 0
    if not args.manifest or not args.evidence:
        parser.error("--run requires --manifest and --evidence")
    manifest = json.loads(Path(args.manifest).read_text())
    return 0 if execute(manifest, args.case, args.evidence, args.campaign_anchor) else 1


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (Refused, OSError, ValueError) as error:
        print(json.dumps({"type": "blocked-or-failed", "reason": str(error)[:512]}))
        sys.exit(2)
